/// A simple inventory that tracks how many units of each item are in stock.
#[derive(Debug, Default)]
pub struct Inventory {
    items: HashMap<String, u32>,
}

#[derive(Debug, PartialEq)]
pub enum InventoryError {
    UnknownItem(String),
    InsufficientStock { item: String, requested: u32, available: u32 },
}

impl fmt::Display for InventoryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InventoryError::UnknownItem(name) => write!(f, "unknown item: {name}"),
            InventoryError::InsufficientStock { item, requested, available } => write!(
                f,
                "cannot remove {requested} of {item}: only {available} in stock"
            ),
        }
    }
}

impl std::error::Error for InventoryError {}

impl Inventory {
    pub fn new() -> Self {
        Self::default()
    }

    /// Adds `count` units of `name`, creating the entry if needed.
    pub fn add(&mut self, name: &str, count: u32) {
        *self.items.entry(name.to_string()).or_insert(0) += count;
    }

    /// Removes `count` units of `name`, failing if the stock is too low.
    pub fn remove(&mut self, name: &str, count: u32) -> Result<(), InventoryError> {
        let available = self
            .items
            .get_mut(name)
            .ok_or_else(|| InventoryError::UnknownItem(name.to_string()))?;
        if *available < count {
            return Err(InventoryError::InsufficientStock {
                item: name.to_string(),
                requested: count,
                available: *available,
            });
        }
        *available -= count;
        Ok(())
    }

